package main

// small enough for registers, too large for SSA
type T struct {
	a, b, c, d, e int
}

//go:noinline
func F() {
	a, b := g(), g()
	h(b, b)
	h(a, g())
	if a.a == 1 {
		a = g()
	}
	h(a, a)
}

//go:noinline
func g() T {
	return T{1, 2, 3, 4, 5}
}

//go:noinline
func h(s, t T) {
	if s != t {
		println("NEQ")
	}
}

func main() { F() }

